// JsxEmitName is $jsxEmitName.
func (m *Machine) JsxEmitName() uint32 {
	var from, c, dotted, kind uint32
	from = m.Ptr
	for {
		if m.Ptr >= m.End {
			if m.Ptr > from {
				m.JsxEmit(rt.Sel32(dotted|rt.B2u(rt.Ld8(m.Mem, int(from))-65 <= 25) != 0, TokenTagComponentJsx, TokenTagJsx), from, m.Ptr)
				if m.EcmaHasTsrx() != 0 {
					kind = m.TsrxRawKind(from, m.Ptr)
				}
			}
			return kind
		}
		c = rt.Ld8(m.Mem, int(m.Ptr))
		if m.JsxNameCont(c) == 0 {
			if m.Ptr > from {
				m.JsxEmit(rt.Sel32(dotted|rt.B2u(rt.Ld8(m.Mem, int(from))-65 <= 25) != 0, TokenTagComponentJsx, TokenTagJsx), from, m.Ptr)
				if m.EcmaHasTsrx() != 0 {
					kind = m.TsrxRawKind(from, m.Ptr)
				}
			}
			return kind
		}
		if c == '.' {
			dotted = 1
		}
		m.Ptr++
	}
}

// JsxOpenContainer is $jsxOpenContainer.
func (m *Machine) JsxOpenContainer() {
	m.NextToken()
	if m.Rhs-m.Lhs == 2 {
		m.TsrxEmitContainerOpen(m.Lhs, m.Rhs)
	} else {
		m.JsxEmit(TokenPunctuationBracket, m.Lhs, m.Rhs)
	}
	m.JsxPush(3, m.BraceDepth-1)
	m.PrevTok = LexLBrace
}

// JsxTagStep is $jsxTagStep.
