// StataWordHl is $stataWordHl.
func (m *Machine) StataWordHl(lhs uint32, rhs uint32) uint32 {
	var v, n uint32
	var w uint64
	v = m.LexKeywordValue(lhs, rhs, 52752, 31, 136)
	n = rhs - lhs
	if int32(v) >= 0 || n < 6 {
		return v
	}
	w = rt.Ld64(m.Mem, int(lhs))
	if n == 6 {
		w &= 0xffffffffffff
		if w == 0x65646f636572 || w == 0x65646f636564 {
			return TokenKeyword
		}
	}
	if n == 7 {
		w &= 0xffffffffffffff
		if w == 0x65706168736572 || w == 0x65726f74736572 || w == 0x65666468676572 {
			return TokenKeyword
		}
	}
	if n == 8 {
		if w == 0x65756e69746e6f63 {
			return TokenKeywordControl
		}
		if w == 0x656c6966706d6574 {
			return TokenKeywordDeclaration
		}
	}
	return 0xffffffff
}

// StataTwoBreaks is $stataTwoBreaks.
